package cn.paletale.companion;
import com.google.gson.*;
import java.util.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import static cn.paletale.companion.MarketTheme.*;
/** UUID favorites and archive favorites share this private collection, including unregistered SMC players. */
final class WorldFavoritesScreen extends WindowScreen {
 private final Screen parent;private final MarketApi market;private final java.util.function.Supplier<String> tokens;private final WorldApi api=new WorldApi();private boolean online,loading,started;private String token,error="";private List<JsonObject> rows=List.of();private int page=1,size,total,generation;
 WorldFavoritesScreen(Screen parent,MarketApi market,boolean online){this(parent,market,online,PaleTaleClient.ACCOUNT::token);}
 WorldFavoritesScreen(Screen parent,MarketApi market,boolean online,java.util.function.Supplier<String> tokens){super(Component.literal("收藏玩家"));this.parent=parent;this.market=market;this.online=online;this.tokens=tokens;}
 @Override protected void init(){fitWindow();int cols=Math.max(2,(width-24)/84),count=Math.max(1,Math.min(4,(height-115)/48)),nextSize=Math.min(48,cols*count);if(started&&size!=nextSize){size=nextSize;page=1;started=false;}size=nextSize;String actor=tokens.get();if(!Objects.equals(token,actor)){generation++;token=actor;rows=List.of();total=0;started=false;loading=false;}
  addRenderableWidget(new Action("← 返回",12,14,64,18,false,null,b->onClose()));addRenderableWidget(new Action("刷新",width-70,14,58,18,false,null,b->{PaleTaleClient.FAVORITE_PRESENCE.invalidate(token,market.site());load();}));
  addRenderableWidget(new Action("全部收藏",12,46,74,18,!online,null,b->{online=false;rows=List.of();page=1;load();}));addRenderableWidget(new Action("收藏在线",90,46,74,18,online,null,b->{online=true;rows=List.of();page=1;load();}));
  int cw=(width-24-(cols-1)*6)/cols,ch=Math.max(40,Math.min(94,(height-115-(count-1)*6)/count));
  for(int i=0;i<rows.size();i++){var row=rows.get(i);int x=12+i%cols*(cw+6),y=70+i/cols*(ch+6);var card=new FavoriteCard(row,x,y,cw,ch);addRenderableWidget(card);var remove=addRenderableWidget(new Action("取消收藏 "+WorldShopTable.value(row,"name"),x+cw-21,y+2,18,16,false,null,b->remove(row)));remove.setDisplayLabel("★");remove.active=!loading;}
  addRenderableWidget(new Action("上一页",12,height-29,60,18,false,null,b->{page--;load();})).active=!loading&&page>1;addRenderableWidget(new Action("下一页",width-72,height-29,60,18,false,null,b->{page++;load();})).active=!loading&&page*size<total;
  if(!started&&token!=null)load();if(token==null)error="请先登录后查看收藏玩家。";
 }
 private void load(){if(token==null)return;started=true;loading=true;error="";int run=++generation;String actor=token;api.call(market.site(),"/api/mcmod/world/favorites?view="+(online?"online":"all")+"&page="+page+"&size="+size,actor,null).whenComplete((value,failure)->minecraft.execute(()->{if(run!=generation||!Objects.equals(actor,tokens.get()))return;loading=false;if(failure!=null)error=WorldApi.problem(failure);else try{if(value.get("version").getAsInt()!=1||value.getAsJsonArray("players").size()>size)throw new IllegalArgumentException();var parsed=new ArrayList<JsonObject>();for(var el:value.getAsJsonArray("players")){var row=el.getAsJsonObject();if(!WorldShopTable.value(row,"uuid").matches("[a-f0-9]{32}"))throw new IllegalArgumentException();parsed.add(row);}rows=List.copyOf(parsed);total=value.get("total").getAsInt();page=value.get("page").getAsInt();if(value.has("complete")&&!value.get("complete").getAsBoolean())error="部分收藏的身份暂时无法核对，可稍后刷新。";}catch(RuntimeException invalid){error="收藏数据暂不可用。";}if(minecraft.screen==this)rebuildWidgets();}));rebuildWidgets();}
 private void remove(JsonObject row){if(loading||token==null)return;loading=true;int run=++generation;String actor=token;var body=new JsonObject();body.add("uuid",row.get("uuid"));body.addProperty("on",false);var requestSite=market.site();long requestAccount=FavoritePresenceWatch.currentAccountId();api.call(requestSite,"/api/mcmod/world/favorites",actor,body).whenComplete((value,failure)->minecraft.execute(()->{if(failure==null){DiskPages.clear(DiskPages.owner(requestSite));WorldEntityScreen.clearFavoriteCache();}if(failure==null)PaleTaleClient.FAVORITE_PRESENCE.changed(actor,requestSite,requestAccount,body.get("uuid").getAsString(),WorldShopTable.value(row,"name"),false);if(run!=generation||!Objects.equals(actor,tokens.get()))return;loading=false;if(failure!=null){error="取消收藏未保存，请重试。";if(minecraft.screen==this)rebuildWidgets();}else if(minecraft.screen==this)load();}));rebuildWidgets();}
 @Override protected void renderWindow(GuiGraphics g,int mx,int my,float delta){super.renderWindow(g,mx,my,delta);text(g,online?"收藏在线玩家":"收藏玩家",86,18,width-160,INK);text(g,"第 "+page+" / "+Math.max(1,(total+size-1)/Math.max(1,size))+" 页 · 共 "+total+" 人",78,height-24,width-156,MUTED);if(!error.isEmpty())text(g,error,12,height-43,width-24,MarketTheme.c(0xFF985326));else if(loading)text(g,"正在读取收藏…",12,height-43,width-24,MUTED);else if(rows.isEmpty())text(g,"暂无符合条件的收藏玩家。",14,80,width-28,MUTED);}
 @Override public void tick(){super.tick();if(!Objects.equals(token,tokens.get()))rebuildWidgets();}
 @Override public void removed(){generation++;loading=false;started=false;rows=List.of();total=0;}
 @Override public void onClose(){minecraft.setScreen(parent);}
 private final class FavoriteCard extends ArchiveCardButton {
  FavoriteCard(JsonObject row,int x,int y,int w,int h){super(WorldPortrait.favorite(row),market,x,y,w,h,b->{if(row.has("eligible")&&row.get("eligible").getAsBoolean()&&row.get("current").getAsBoolean())minecraft.setScreen(new WorldEntityScreen(WorldFavoritesScreen.this,market,"player",WorldShopTable.value(row,"name")));else if(row.has("playerId")&&!row.get("playerId").isJsonNull())minecraft.setScreen(new ArchiveDetailScreen(WorldFavoritesScreen.this,market,ArchiveData.Kind.PLAYERS,row.get("playerId").getAsInt()));});active=!loading&&(row.has("eligible")&&row.get("eligible").getAsBoolean()&&row.get("current").getAsBoolean()||row.has("playerId")&&!row.get("playerId").isJsonNull());}
  @Override public boolean mouseClicked(net.minecraft.client.input.MouseButtonEvent event,boolean twice){if(event.x()>=getX()+getWidth()-22&&event.y()<getY()+20)return false;return super.mouseClicked(event,twice);}
 }
}
